import React, { useEffect, useState } from 'react';
import Box from '../components/Box';
import './HomePage.css';
import Menu from '../components/Menu';

const HomePage = () => {
  const [boxes, setBoxes] = useState([]);
  const [descriptions, setDescriptions] = useState({});
  const [selectedBox, setSelectedBox] = useState(null);

  useEffect(() => {
    fetch('/data/boxes.json')
      .then((response) => {
        console.log('Fetch response:', response);
        return response.json();
      })
      .then((data) => {
        console.log('Fetched data:', data);
        setBoxes(data);
      })
      .catch((error) => console.error('Error loading boxes:', error));
  }, []);

  useEffect(() => {
    fetch('/data/descriptions.json')
      .then((response) => response.json())
      .then((data) => setDescriptions(data))
      .catch((error) => console.error('Error loading descriptions:', error));
  }, []);

  const handleBoxClick = (box) => {
    setSelectedBox({ ...box, description: descriptions[box.id] || 'Descripción no disponible' });
  };

  return (
    <div className="home-page">
      <Menu />
      <h1>Components</h1>
      <div className="content">
        <div className="box-container">
          {boxes.map((box) => (
            <Box key={box.id} name={box.name} onClick={() => handleBoxClick(box)} />
          ))}
        </div>
        <div className="box-description">
          {selectedBox ? (
            <div>
              <h2>{selectedBox.name}</h2>
              <p>{selectedBox.description}</p>
            </div>
          ) : (
            <p>Haz clic en una caja para ver la descripción</p>
          )}
        </div>
      </div>
    </div>
  );
};

export default HomePage;
